use super::*;

/// Read what the device currently has: the sha behind `current` and behind `previous`.
///
/// A device that cannot be reached yields `None` for everything rather than an error, because "I could
/// not tell" is a legitimate answer for `status` and must not read as "it has nothing".
pub fn read_state(device: &Device, name: &str) -> crate::plan::RemoteState {
    let script = format!(
        "r=$HOME/{REMOTE_ROOT}; \
         c=$(readlink \"$r/{name}.current\" 2>/dev/null); \
         p=$(readlink \"$r/{name}.previous\" 2>/dev/null); \
         echo \"cur=${{c##*-}}\"; echo \"prev=${{p##*-}}\"; echo \"arch=$(uname -m)\""
    );
    match ssh(device, &script) {
        Ok(out) => parse_state(&out),
        Err(_) => crate::plan::RemoteState::default(),
    }
}
